// Generator for the 151 Trading Strategies research files (planning only, no trading).
//
//   bun run research:backtest-151            # write strategies.csv, index.md and universe.md
//   bun run research:backtest-151 -- --check # exit 1 if a generated file is out of date
//
// strategies.json and universe.json in research/backtests/151-strategies/ are the sources of
// truth. Do not edit the generated files by hand. Ported from the PR #4 build_index.py.
import { existsSync } from "node:fs";
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { z } from "zod";

export const RESEARCH_DIR = "research/backtests/151-strategies";

const list = z.array(z.string());

const strategySchema = z.object({
  section: z.string().min(1),
  name: z.string().min(1),
  name_es: z.string(),
  chapter: z.number().int(),
  asset_class: z.string().min(1),
  is_variant: z.boolean(),
  rule_summary: z.string().min(1),
  instruments: list,
  required_data: list,
  frequency: z.string().min(1),
  paper_backtestable: z.enum(["yes", "partial", "no"]),
  backtest_note: z.string().min(1),
  wave: z.number().int(),
  harness_primary: z.string(),
  nautilus_fit: z.string(),
  roboquant_fit: z.string(),
  data_sources: list,
  gaps: list,
  universe_groups: list,
});

export const strategiesDocSchema = z.object({
  source: z.object({
    title: z.string(),
    authors: list,
    ssrn: z.string(),
    text_used: z.string(),
    english_names: z.string(),
  }),
  count: z.number().int(),
  strategies: z.array(strategySchema),
});

const groupSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  profile: z.string(),
  source: z.string(),
  strategies: list,
  indexes: list.optional(),
  etfs: list.optional(),
  stocks: list.optional(),
  futures: list.optional(),
  fx: list.optional(),
  crypto: list.optional(),
  series: list.optional(),
});

export const universeSchema = z.object({
  as_of: z.string(),
  swinglytics_snapshot: z.string(),
  note: z.string(),
  groups: z.array(groupSchema),
});

export type StrategiesDoc = z.infer<typeof strategiesDocSchema>;
export type Universe = z.infer<typeof universeSchema>;
type Strategy = StrategiesDoc["strategies"][number];

const CSV_FIELDS = [
  "section",
  "name",
  "asset_class",
  "is_variant",
  "frequency",
  "wave",
  "harness_primary",
  "nautilus_fit",
  "roboquant_fit",
  "paper_backtestable",
  "instruments",
  "required_data",
  "data_sources",
  "gaps",
  "universe_groups",
  "rule_summary",
  "backtest_note",
  "name_es",
] as const satisfies readonly (keyof Strategy)[];

const MEMBER_LABELS = [
  ["indexes", "index"],
  ["etfs", "ETF"],
  ["stocks", "stock"],
  ["futures", "fut"],
  ["fx", "FX"],
  ["crypto", "crypto"],
  ["series", "series"],
] as const;

// Minimal CSV quoting (same output as Python's csv.QUOTE_MINIMAL).
export const csvField = (value: string): string =>
  /[",\r\n]/u.test(value) ? `"${value.replaceAll('"', '""')}"` : value;

const csvValue = (value: Strategy[keyof Strategy]): string => {
  if (Array.isArray(value)) {
    return value.join("; ");
  }
  return String(value);
};

export const buildCsv = (doc: StrategiesDoc): string => {
  const rows = doc.strategies.map((strategy) =>
    CSV_FIELDS.map((field) => csvField(csvValue(strategy[field]))).join(",")
  );
  return `${[CSV_FIELDS.join(","), ...rows].join("\n")}\n`;
};

// One Markdown table cell: escape pipes and asterisks (F* is a price, not emphasis), fold line breaks.
const cell = (text: string): string =>
  text.replaceAll("|", "\\|").replaceAll("*", "\\*").replaceAll("\n", " ");

// Wrap bare URLs in angle brackets so Markdown renders them as links (markdownlint MD034).
export const autolink = (text: string): string =>
  text.replace(/(?<!<|\]\()(https?:\/\/[^\s)>]+)/gu, "<$1>");

const row = (cells: readonly (string | number)[]): string =>
  `|${cells.join("|")}|`;

export const buildIndex = (doc: StrategiesDoc): string => {
  const { source } = doc;
  const out = [
    "# 151 Trading Strategies: strategy index",
    "",
    "Generated by `bun run research:backtest-151` from `strategies.json`. Do not edit by hand.",
    "",
    `Source: ${source.title}, ${source.authors.join(" and ")}. SSRN: <${source.ssrn}>. Text used: ${autolink(source.text_used)}. English names: ${autolink(source.english_names)}.`,
    "",
    "Rule summaries are paraphrases written for planning. Check the paper before you implement a rule.",
    "",
    "Columns: **Wave** 1 = data on hand or free, 2 = needs one new data source, 3 = needs OTC/model prices or a proxy, 0 = no market backtest. **Harness** is the primary engine. **RQ** = fits the roboquant.dev engine (CME futures only).",
  ];
  let chapter: number | undefined;
  for (const strategy of doc.strategies) {
    if (strategy.chapter !== chapter) {
      chapter = strategy.chapter;
      out.push(
        "",
        `## ${chapter}. ${strategy.asset_class}`,
        "",
        row([
          "Section",
          "Strategy",
          "Freq.",
          "Wave",
          "Harness",
          "RQ",
          "Rule summary",
        ]),
        row(["---", "---", "---", "---", "---", "---", "---"])
      );
    }
    const name = `${strategy.is_variant ? "↳ " : ""}${strategy.name}`;
    out.push(
      row([
        strategy.section,
        cell(name),
        strategy.frequency,
        strategy.wave,
        strategy.harness_primary,
        strategy.roboquant_fit === "none" ? "" : "yes",
        cell(strategy.rule_summary),
      ])
    );
  }
  return `${out.join("\n")}\n`;
};

export const buildUniverse = (
  universe: Universe,
  doc: StrategiesDoc
): string => {
  const names = new Map(doc.strategies.map((s) => [s.section, s.name]));
  const out = [
    "# Backtest universe: 20 contrasting groups",
    "",
    "Generated by `bun run research:backtest-151` from `universe.json`. Do not edit by hand.",
    "",
    `As of ${universe.as_of}. Swinglytics snapshot \`${universe.swinglytics_snapshot}\` (read by \`research/backtests/151-strategies/scripts/swinglytics_universe.py\` with the market-watch-swing parser).`,
    "",
    universe.note,
    "",
    row(["Group", "Name", "Profile", "Source", "Members", "Strategies"]),
    row(["---", "---", "---", "---", "---", "---"]),
  ];
  for (const group of universe.groups) {
    const members = MEMBER_LABELS.flatMap(([key, label]) => {
      const values = group[key] ?? [];
      return values.length > 0 ? [`${label}: ${values.join(", ")}`] : [];
    });
    out.push(
      row([
        group.id,
        cell(group.name),
        cell(group.profile),
        cell(group.source),
        cell(members.join("; ")),
        group.strategies.length,
      ])
    );
  }
  out.push("", "## Strategies per group", "");
  for (const group of universe.groups) {
    const sections =
      group.strategies
        .map((section) => `${section} ${names.get(section) ?? "(unknown)"}`)
        .join(", ") || "none";
    out.push(`- **${group.id} ${group.name}**: ${sections}`);
  }
  return `${out.join("\n")}\n`;
};

export const renderFiles = (
  doc: StrategiesDoc,
  universe: Universe
): Readonly<Record<string, string>> => ({
  "strategies.csv": buildCsv(doc),
  "index.md": buildIndex(doc),
  "universe.md": buildUniverse(universe, doc),
});

const readText = async (path: string): Promise<string | undefined> =>
  existsSync(path) ? await readFile(path, "utf8") : undefined;

export const loadSources = async (
  dir: string
): Promise<Readonly<{ doc: StrategiesDoc; universe: Universe }>> => ({
  doc: strategiesDocSchema.parse(
    JSON.parse(await readFile(join(dir, "strategies.json"), "utf8"))
  ),
  universe: universeSchema.parse(
    JSON.parse(await readFile(join(dir, "universe.json"), "utf8"))
  ),
});

type Output = Readonly<{ write: (text: string) => unknown }>;

export const runBacktest151Cli = async (
  args: readonly string[],
  io: Readonly<{ root: string; stdout: Output; stderr: Output }>
): Promise<number> => {
  const unknown = args.filter((arg) => arg !== "--check");
  if (unknown.length > 0) {
    io.stderr.write(`unknown argument: ${unknown.join(" ")}\n`);
    return 2;
  }
  const check = args.includes("--check");
  const dir = join(io.root, RESEARCH_DIR);
  const { doc, universe } = await loadSources(dir);
  const files = Object.entries(renderFiles(doc, universe));
  if (!check) {
    for (const [name, text] of files) {
      await writeFile(join(dir, name), text, "utf8");
    }
    io.stdout.write(`wrote ${files.map(([name]) => name).join(", ")}\n`);
    return 0;
  }
  const stale: string[] = [];
  for (const [name, text] of files) {
    if ((await readText(join(dir, name))) !== text) {
      stale.push(name);
    }
  }
  if (stale.length > 0) {
    io.stderr.write(`out of date: ${stale.join(", ")}\n`);
    return 1;
  }
  io.stdout.write("ok\n");
  return 0;
};
